import { RUNTIME_CAPACITY } from "../../../scripts/lib/runtime-capacity.mjs";
// SPDX-License-Identifier: Apache-2.0

// TCRN-CROSS-STORY-479 R1, AC1, AC3 (MIN-227 D28): the SKILL.md of the Mana Orchestrate skill is
// generated by the engine for its own version and is never written by hand. It carries the
// English discovery description as its frontmatter description, the navigation table (which
// engine verb to run at which moment), how to run a verb, the three-step routine, and one line
// that points to references/, which the host loads only for an install-type task. An everyday
// session loads this file and nothing else, so it stays under SKILL_MARKDOWN_BYTE_LIMIT bytes and
// keeps the wizard text out.
//
// Every verb the table names must be a verb of the engine the file is generated by: the caller
// passes the names of its command catalog, and a name the catalog does not carry refuses the whole
// rendering with SKILL_NAVIGATION_VERB_UNKNOWN, so a model never reads a verb that does not run.
// The navigation text also carries the decision rule of TCRN-CROSS-STORY-475 R4: a decision is
// recorded as soon as the model judges it one, and the reply ends by echoing its number.
//
// Every text is a constant in this module, and it reads no file: a packaged engine is one script,
// and a text kept anywhere else would not travel with it. tests/fixtures/skill/description-a.en.txt
// pins the discovery description, and tests/skill-render.test.mjs compares the two.

import { DEVICE_HOME_ENVIRONMENT_VARIABLE } from "./device-home.js";
import { isEngineVersion } from "./format-version.js";
import { BRAND, DIRECTORY } from "./names.js";

/** SKILL.md is always shorter than this many bytes (UTF-8). */
export const SKILL_MARKDOWN_BYTE_LIMIT = RUNTIME_CAPACITY.bufferBytes;

export const SKILL_RENDER_REASON_CODES = Object.freeze([
  "SKILL_MARKDOWN_TOO_LARGE",
  "SKILL_NAVIGATION_VERB_UNKNOWN",
  "SKILL_VERSION_INVALID",
] as const);
export type SkillRenderReasonCode = typeof SKILL_RENDER_REASON_CODES[number];

export class SkillRenderError extends Error {
  readonly reasonCode: SkillRenderReasonCode;
  readonly details: Readonly<Record<string, string>>;

  constructor(reasonCode: SkillRenderReasonCode, message: string, details: Readonly<Record<string, string>> = {}) {
    super(message);
    this.name = "SkillRenderError";
    this.reasonCode = reasonCode;
    this.details = details;
  }
}

function fail(reasonCode: SkillRenderReasonCode, message: string, details: Readonly<Record<string, string>> = {}): never {
  throw new SkillRenderError(reasonCode, message, details);
}

/** Description A, extended with coding-task discovery for Einzbern-managed projects. */
export const SKILL_DESCRIPTION = "The Grail grants wishes; Mana Orchestrate makes the mana flow to the right place at the right moment. It brings Einzbern, project memory, into Claude Code, Codex, Kiro, Antigravity and DeepSeek Harness: recall before you start, write results back to the work item, record decisions as minutes, keep lessons as cards. Where Einzbern is not installed yet, it is the wizard: install, restore, update, migrate, uninstall, health check. Use for Einzbern-managed coding, work items, knowledge cards, minutes, .ether, Atelier, installation or updates." as const;

/** One row of the navigation table: at this moment, run these verbs, like this. */
export interface SkillNavigationEntry {
  readonly moment: string;
  readonly verbs: readonly string[];
  readonly action: string;
}

// Keep routine guidance compact; detailed installation and optional scheduling live in install.md.
export const SKILL_NAVIGATION: readonly SkillNavigationEntry[] = Object.freeze([
  {
    moment: "Starting work",
    verbs: ["recall", "recall-read", "rule-list"],
    action: "`recall --view candidates --query \"<task>\" --at <UTC>`. Rephrase if useful. `recall-read --refs` is optional. Sessions read their live work. Rules: `specs/work-practices-v1.md`; Kiro: `references/kiro-specs.md`; Dot blocker/privacy-publication: `specs/dot-rules-v1.md`.",
  },

  {
    moment: "Draft by type",
    verbs: ["work-draft"],
    action: "Types/defects, inherited constraints, stages: specs/work-content-v1.md. One record, not a second acceptance copy.",
  },
  {
    moment: "Full text",
    verbs: ["work-show", "work-content-context", "minutes-show", "work-project-context", "execution-prepare", "execution-record", "execution-evidence"],
    action: "Read `work-show --id <id>` or `minutes-show --id <id>`. Use each target's `handoff` for dispatch/gates (`EINZBERN_PROJECT_CONTEXT`). Unresolved targets block dependent work. `--execution-request` requires `dispatchAdmitted=true`, selected runner/model/effort. Keep that selection. Validate `execution-evidence --from-file <json>`. Keep raw stdout/stderr/exit code. Evidence validation grants no execution permission. `specs/context-v1.md`, `specs/dispatch-admission-evidence-v1.md`.",
  },
  {
    moment: "Native dispatch (Codex, Claude, dot, Kiro CLI, Antigravity, Devin)",
    verbs: ["execution-policy-resolve", "execution-host-prepare", "execution-host-record", "execution-host-evidence", "execution-codex-peer-record", "execution-codex-peer-evidence", "execution-antigravity-swarm-record", "execution-antigravity-swarm-evidence"],
    action: "Class fallback/hard limits. Use normal prompt reports. Parent reads before dispatch, child reads before work. scope/permission, targets=[], machine-assembled raw returns/reports. Dot model selection is host-managed. Host Integrations/controller details: specs/kiro-host-v1.md, docs/antigravity-swarm-controller.md, specs/devin-host-v1.md. attempt association and failure outcomes: --binding/--prior; unknown/cancel/finality/review: specs/host-fallback-v1.md.",
  },
  {
    moment: "Shared submit",
    verbs: ["shared-submit-plan", "shared-submit-evidence", "shared-submit-advisory-read", "shared-submit-advisory-write"],
    action: "Complete baseline/engine changes; one complete pre-submit refresh + engine reapply; serial handoff; segments before manifest; verify remote bytes + complete destination replay; observe release. Advisory is not a lock; absence/age grants nothing. Query unknown publication before retry. `specs/shared-submit-v1.md`.",
  },
  {
    moment: "Done",
    verbs: ["work-transition", "work-annotate"],
    action: "Actor/readback. Pending != complete. Compare original source, behavior and assertions; structure is not semantic acceptance. Dot/local consumption separately; unavailable remains unverified. specs/batch-execution-v1.md.",
  },
  {
    moment: "Decision",
    verbs: ["minutes-record"],
    action: "As soon as you judge, record D1–Dn; end with `已记 <minutes key> Dn` (`Recorded <minutes key> Dn`); --supersedes/--withdraws/--coexists.",
  },
  {
    moment: "Lesson",
    verbs: ["knowledge-create", "knowledge-capture"],
    action: "Capture at most five new sourced lessons; read back. Stable IDs, repository-relative evidence paths. No progress in AGENTS.",
  },
  {
    moment: "Config / UI",
    verbs: ["settings-catalog", "variable-list"],
    action: "AGENTS: principles only. Scoped config; optional `design.authority`: specs/configuration-contract-v1.md.",
  },
].map((entry) => Object.freeze({ ...entry, verbs: Object.freeze([...entry.verbs]) })));

// Verbs the text names outside the table.
const OTHER_NAMED_VERBS: readonly string[] = Object.freeze(["commands", "engine-list", "library-resolve", "setup", "work-list", "work-create", "work-batch"]);

/** Every engine verb SKILL.md names, the table's first and in its order, without repeats. */
export function skillNamedVerbs(): readonly string[] {
  return [...new Set([...SKILL_NAVIGATION.flatMap((entry) => entry.verbs), ...OTHER_NAMED_VERBS])];
}

export interface RenderSkillMarkdownInput {
  // The engine version the file is generated for.
  readonly version: string;
  // The names in that engine's command catalog.
  readonly catalogNames: readonly string[];
}

function navigationRow(entry: SkillNavigationEntry): string {
  return `| ${entry.moment} | ${entry.verbs.map((verb) => `\`${verb}\``).join(", ")} | ${entry.action} |`;
}

/**
 * SKILL.md for one engine version (TCRN-CROSS-STORY-479 R1): the frontmatter (name and the
 * discovery description), the navigation table and how to run a verb, the three-step routine,
 * and the pointer to references/. Refuses a verb the catalog does not carry, a version that is not
 * a release version, and a result of SKILL_MARKDOWN_BYTE_LIMIT bytes or more.
 */
export function renderSkillMarkdown(input: RenderSkillMarkdownInput): string {
  if (!isEngineVersion(input.version)) {
    fail("SKILL_VERSION_INVALID", `${String(input.version)} is not an engine release version`, { version: String(input.version) });
  }
  const catalog = new Set(input.catalogNames);
  for (const verb of skillNamedVerbs()) {
    if (!catalog.has(verb)) {
      fail("SKILL_NAVIGATION_VERB_UNKNOWN", `${verb} is not a verb of engine ${input.version}; the navigation would name a verb that does not run`, { verb, version: input.version });
    }
  }
  const lines = [
    "---",
    `name: ${BRAND.helper.id}`,
    // A YAML double-quoted scalar: the description holds ": ", which a plain scalar cannot.
    `description: ${JSON.stringify(SKILL_DESCRIPTION)}`,
    "---",
    "",
    `# ${BRAND.helper.name}`,
    "",
    `Navigation for ${BRAND.engine.name} ${input.version}: generated.`,
    "",
    "Execution protocol: tcrn.host-execution-request.v1.",
    "",
    "## Navigation",
    "",
    `Root: absolute \`${DEVICE_HOME_ENVIRONMENT_VARIABLE}\` or \`~/${DIRECTORY.device}\`. Flags: \`e <verb> --help\`; --at UTC. Read engine bundle \`specs/\` beside \`scripts/\`, not this Skill.`,
    "",
    "Local writes queue together, not cross-device exclusion. Remote submission: serial handoff. Dot installs no native hook, lifecycle manager or sync service.",
    "",
    "| Moment | Verb | What to do |",
    "| --- | --- | --- |",
    ...SKILL_NAVIGATION.map(navigationRow),
    "",
    "Coding: `specs/coding-style-v1.md`.",
    "",
    "Patch fixes, minor adds, major breaks. `e engine-list`: `current.version`.",
    "",
    "## Core commands",
    "",
    "work-list --full true shows content. work-create/work-batch write. `minutes-record --decisions-file <json>` accepts {text,title,tags} entries or strings. Check verifiedReadback/localCommitted, delivery.",
    "",
    "Codex: owning App Server JSON-RPC `initialize` → `hooks/list` for `$PWD`; fresh project-bound `--codex-admission` from raw result; SHA-256 hook `sourcePath`/config hashes. docs/codex-native-controller.md. Reobserve within five minutes; require `ok=true` and `hooks-present.detail.codexGuard.ready`.",
    "",
    "```sh",
    "e() { node \"${EINZBERN_HOME:-$HOME/.einzbern}/engine/einzbern.mjs\" \"$@\"; }",
    "w=\"$(e library-resolve --cwd \"$PWD\" | jq -r .libraryPath)\"",
    "p=\"$(e rule-list --project . | jq -r .projectId)\"",
    "e doctor --project . --codex-admission codex-admission.json",
    "e rule-list --workspace=\"$w\" --project-id=\"$p\"",
    "e work-show --workspace=\"$w\" --external-key TCRN-CROSS-STORY-692",
    "printf '%s' '[\"已核验 1,392 个文件\"]' > decisions.json",
    "e minutes-record --workspace=\"$w\" --project-id=\"$p\" --title check --summary done --decisions-file decisions.json --actor agent:codex --external-key m$(date +%s) --at \"$(date -u +%FT%TZ)\"",
    "```",
    "",
    "## Three steps",
    "",
    "1. `npx skills add tpmoonchefryan/mana-orchestrate`.",
    `2. Say "install ${BRAND.engine.name}"; setup hooks or independent dot target (install.md).`,
    "3. Installation, policy changes, restoration and publication need their own approvals. Dot/schedules: references/owner-extensions.md.",
    "",
    "## Install-type tasks",
    "",
    "Install/restore/update/repair/rollback/migrate/uninstall/doctor: `references/` (`install.md`, `restore.md`, `update.md`, `migrate.md`, `uninstall.md`, `doctor.md`); Dot: `owner-extensions.md`; never load them for any other work.",
    "",
  ];
  const markdown = lines.join("\n");
  const bytes = Buffer.byteLength(markdown, "utf8");
  if (bytes >= SKILL_MARKDOWN_BYTE_LIMIT) {
    fail("SKILL_MARKDOWN_TOO_LARGE", `SKILL.md would be ${bytes} bytes; it must stay under ${SKILL_MARKDOWN_BYTE_LIMIT}`, { bytes: String(bytes), limit: String(SKILL_MARKDOWN_BYTE_LIMIT) });
  }
  return markdown;
}

/** Install-time compatibility check, not a runtime prerequisite for native tools. */
export const HOST_SKILL_PROTOCOL_MARKER = "Execution protocol: tcrn.host-execution-request.v1.";
export function checkHostSkillCompatibility(markdown: string, commandNames: readonly string[]): { readonly compatible: boolean; readonly missing: readonly string[]; readonly protocol: "host-native-v1" | "legacy" } {
  if (!markdown.includes(HOST_SKILL_PROTOCOL_MARKER)) return { compatible: true, missing: [], protocol: "legacy" };
  const required = [
    "execution-host-prepare",
    "execution-host-record",
    "execution-host-evidence",
    ...(markdown.includes("`execution-codex-peer-record`") ? ["execution-codex-peer-record", "execution-codex-peer-evidence"] : []),
    ...(markdown.includes("`execution-antigravity-swarm-record`") ? ["execution-antigravity-swarm-record", "execution-antigravity-swarm-evidence"] : []),
  ];
  const missing = required.filter(name => !commandNames.includes(name));
  return { compatible: missing.length === 0, missing, protocol: "host-native-v1" };
}
